"""Fair-budget Route-B ablations; every core solver receives the same wall budget."""
from __future__ import annotations
import argparse,csv,json,os,time
from config import Weights
from data import prepare_instance
from solve_direct_gurobi import INSTANCES,solve_direct_gurobi
from solver_true_benders import solve_true_benders_pipeline

FIELDS="instance seed algorithm status budget runtime ub lb gap root_initial_bound root_final_bound root_bound_improvement master_open_bound master_eta_bound aggregate_recourse_bound aggregate_distance_bound aggregate_balance_bound aggregate_conflict_bound root_opt_cuts root_feas_cuts incumbent_opt_cuts node_opt_cuts incumbent_feas_cuts node_feas_cuts unique_cuts sp_solves sp_total_time callback_time callback_time_share alns_start_ub alns_best_ub alns_improvement cut_strategy aggregate_recourse_lb analytic_recourse_lb alloc_domain anytime_trace".split()
def configs(full=False):
    c=[{"algorithm":"direct","direct":True},{"algorithm":"bbc_weak","aggregate":False,"analytic":False},{"algorithm":"bbc_analytic","aggregate":False,"analytic":True},{"algorithm":"bbc_aggregate","aggregate":True,"analytic":True},{"algorithm":"bbc_aggregate_stabilized","aggregate":True,"analytic":True,"strategy":"stabilized"}]
    if full:c += [{"algorithm":"aggregate_no_node","node":False},{"algorithm":"aggregate_periodic_node","policy":"periodic"},{"algorithm":"aggregate_continuous","domain":"continuous"}]
    return c
def run_one(instance,seed,cfg,budget,threads):
    domain=cfg.get("domain","integer");d=prepare_instance(INSTANCES[instance]());started=time.perf_counter()
    if cfg.get("direct"):
        q=solve_direct_gurobi(d,Weights(),time_limit=budget,mip_gap=.03,alloc_domain=domain,seed=seed,threads=threads);return {"instance":instance,"seed":seed,"algorithm":cfg["algorithm"],"status":q["status_name"],"budget":budget,"runtime":q["runtime"],"ub":q["ub"],"lb":q["lb"],"gap":q["gap"],"alloc_domain":domain}
    r=solve_true_benders_pipeline(d,Weights(),total_core_time=budget,attribute_time=0,enable_refinement=False,alloc_domain=domain,aggregate_recourse_lb=cfg.get("aggregate",True),analytic_recourse_lb=cfg.get("analytic",True),cut_strategy=cfg.get("strategy","standard"),node_cuts=cfg.get("node",True),node_separation_policy=cfg.get("policy","root-only"),seed=seed,threads=threads);root=r.get("phase0_root_prepass",{});main=r.get("phase3_bbc",{});cs=main.get("cut_statistics",{});sp=main.get("sp_statistics",{});alns=r.get("phase2_alns",{});core=r.get("core_best",{})
    trace=[{"time":0.0,"lb":root.get("root_initial_bound") }]+[{"time":x.get("elapsed"),"lb":x.get("bound")} for x in root.get("iteration_trace",[])];trace += main.get("anytime_trace",[])
    return {"instance":instance,"seed":seed,"algorithm":cfg["algorithm"],"status":main.get("status_name","FAILED"),"budget":budget,"runtime":time.perf_counter()-started,"ub":core.get("ub"),"lb":core.get("lb"),"gap":core.get("gap"),"root_initial_bound":root.get("root_initial_bound"),"root_final_bound":root.get("root_final_bound"),"root_bound_improvement":root.get("root_bound_improvement"),"master_open_bound":root.get("master_open_bound"),"master_eta_bound":root.get("master_eta_bound"),"aggregate_recourse_bound":root.get("aggregate_recourse_bound"),"aggregate_distance_bound":root.get("aggregate_distance_bound"),"aggregate_balance_bound":root.get("aggregate_balance_bound"),"aggregate_conflict_bound":root.get("aggregate_conflict_bound"),"root_opt_cuts":root.get("root_optimality_cuts"),"root_feas_cuts":root.get("root_feasibility_cuts"),"incumbent_opt_cuts":cs.get("incumbent_optimality_cuts"),"node_opt_cuts":cs.get("node_optimality_cuts"),"incumbent_feas_cuts":cs.get("incumbent_feasibility_cuts"),"node_feas_cuts":cs.get("node_feasibility_cuts"),"unique_cuts":r.get("total_unique_cuts"),"sp_solves":sp.get("sp_solve_count"),"sp_total_time":sp.get("sp_total_time"),"callback_time":cs.get("callback_time"),"callback_time_share":cs.get("callback_time_share"),"alns_start_ub":alns.get("start_ub"),"alns_best_ub":alns.get("best_ub"),"alns_improvement":alns.get("improvement"),"cut_strategy":cfg.get("strategy","standard"),"aggregate_recourse_lb":cfg.get("aggregate",True),"analytic_recourse_lb":cfg.get("analytic",True),"alloc_domain":domain,"anytime_trace":json.dumps(trace,separators=(",",":"))}
def main():
    p=argparse.ArgumentParser();p.add_argument("--instances",nargs="+",choices=INSTANCES,default=["tiny"]);p.add_argument("--seeds",nargs="+",type=int,default=[0]);p.add_argument("--total-core-time",type=float,default=10);p.add_argument("--threads",type=int,default=1);p.add_argument("--suite",choices=("quick","full"),default="quick");p.add_argument("--output",default="experiments");a=p.parse_args();os.makedirs(a.output,exist_ok=True);rows=[run_one(i,s,c,a.total_core_time,a.threads) for i in a.instances for s in a.seeds for c in configs(a.suite=="full")]
    with open(os.path.join(a.output,"results.csv"),"w",newline="",encoding="utf8") as f:w=csv.DictWriter(f,fieldnames=FIELDS,extrasaction="ignore");w.writeheader();w.writerows(rows)
    with open(os.path.join(a.output,"results.json"),"w",encoding="utf8") as f:json.dump(rows,f,indent=2)
    print(f"wrote {len(rows)} equal-budget rows")
if __name__=="__main__":main()
